import hashlib
import hmac

# パスワードは SHA-256 ハッシュで保持
USERS = {'admin': hashlib.sha256(b'secret').hexdigest()}


def login(user, pw):
    stored = USERS.get(user)
    if stored is None or not isinstance(pw, str):
        return False
    digest = hashlib.sha256(pw.encode()).hexdigest()
    return hmac.compare_digest(stored, digest)

MIN_LEN = 6


def login(user, pw):
    if user != 'admin':
        return False
    return isinstance(pw, str) and len(pw) == MIN_LEN
